from collections import deque


def right_side_view(level_order):
    if not level_order or level_order[0] is None:
        return []
    root = {"val": level_order[0], "left": None, "right": None}
    q = deque([root])
    i = 1
    n = len(level_order)
    while q and i < n:
        node = q.popleft()
        if i < n:
            v = level_order[i]
            i += 1
            if v is not None:
                node["left"] = {"val": v, "left": None, "right": None}
                q.append(node["left"])
        if i < n:
            v = level_order[i]
            i += 1
            if v is not None:
                node["right"] = {"val": v, "left": None, "right": None}
                q.append(node["right"])
    result = []
    level = deque([root])
    while level:
        size = len(level)
        for j in range(size):
            node = level.popleft()
            if j == size - 1:
                result.append(node["val"])
            if node["left"]:
                level.append(node["left"])
            if node["right"]:
                level.append(node["right"])
    return result
